use std::path::{Path, PathBuf};
use std::sync::Arc;
use tokio::sync::{mpsc, RwLock};
use tokio::fs;
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QueueMessage {
    pub id: String,
    pub action: String,
    pub payload: String,
    pub metadata: MessageMetadata,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MessageMetadata {
    pub source: String,
    pub priority: u8,
    pub content_type: String,
}

pub struct ConsumerConfig {
    pub base_dir: PathBuf,
    pub allowed_extensions: Vec<String>,
    pub max_depth: usize,
}

impl ConsumerConfig {
    pub fn new(base_dir: PathBuf) -> Self {
        Self {
            base_dir,
            allowed_extensions: vec!["json".into(), "xml".into(), "txt".into()],
            max_depth: 3,
        }
    }
}

pub struct MessageConsumer {
    config: Arc<ConsumerConfig>,
    state: Arc<RwLock<ConsumerState>>,
}

#[derive(Default)]
struct ConsumerState {
    processed_count: u64,
    last_error: Option<String>,
}

impl MessageConsumer {
    pub fn new(config: ConsumerConfig) -> Self {
        Self {
            config: Arc::new(config),
            state: Arc::new(RwLock::new(ConsumerState::default())),
        }
    }

    pub async fn start(&self, mut rx: mpsc::Receiver<QueueMessage>) {
        while let Some(msg) = rx.recv().await {
            let config = self.config.clone();
            let state = self.state.clone();
            tokio::spawn(async move {
                if let Err(e) = process_message(&config, &state, msg).await {
                    let mut s = state.write().await;
                    s.last_error = Some(e.to_string());
                }
            });
        }
    }
}

async fn process_message(
    config: &ConsumerConfig,
    state: &Arc<RwLock<ConsumerState>>,
    msg: QueueMessage,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    match msg.action.as_str() {
        "list_resources" => {
            let listing = resolve_and_list(config, &msg.payload).await?;
            emit_response(&msg.id, listing).await?;
        }
        "fetch_resource" => {
            let content = fetch_resource(config, &msg.payload).await?;
            emit_response(&msg.id, vec![content]).await?;
        }
        _ => {
            return Err(format!("Unknown action: {}", msg.action).into());
        }
    }
    let mut s = state.write().await;
    s.processed_count += 1;
    Ok(())
}

async fn resolve_and_list(
    config: &ConsumerConfig,
    relative_path: &str,
) -> Result<Vec<String>, Box<dyn std::error::Error + Send + Sync>> {
    let sanitized = sanitize_path_component(relative_path);
    let target = config.base_dir.join(&sanitized);

    // Canonicalize both paths for comparison
    let canonical_base = fs::canonicalize(&config.base_dir).await?;
    let canonical_target = fs::canonicalize(&target).await?;

    // Security check: verify target is within base directory
    if !is_within_base(&canonical_base, &canonical_target) {
        return Err("Access denied: path traversal detected".into());
    }

    let depth = compute_depth(&canonical_base, &canonical_target);
    if depth > config.max_depth {
        return Err("Access denied: max depth exceeded".into());
    }

    list_directory_entries(&canonical_target, &config.allowed_extensions).await
}

fn sanitize_path_component(input: &str) -> String {
    input
        .replace("..", "")
        .replace('\\', "/")
        .trim_start_matches('/')
        .to_string()
}

fn is_within_base(base: &Path, target: &Path) -> bool {
    // Use proper path prefix checking via components
    target.starts_with(base)
}

fn compute_depth(base: &Path, target: &Path) -> usize {
    let base_components: Vec<_> = base.components().collect();
    let target_components: Vec<_> = target.components().collect();
    target_components.len().saturating_sub(base_components.len())
}

async fn list_directory_entries(
    dir: &Path,
    allowed_extensions: &[String],
) -> Result<Vec<String>, Box<dyn std::error::Error + Send + Sync>> {
    let mut entries = Vec::new();
    let mut read_dir = fs::read_dir(dir).await?;

    while let Some(entry) = read_dir.next_entry().await? {
        let file_type = entry.file_type().await?;
        let name = entry.file_name().to_string_lossy().to_string();

        if file_type.is_dir() {
            entries.push(format!("[DIR] {}", name));
        } else if has_allowed_extension(&name, allowed_extensions) {
            entries.push(name);
        }
    }

    Ok(entries)
}

fn has_allowed_extension(filename: &str, allowed: &[String]) -> bool {
    if let Some(ext) = Path::new(filename).extension() {
        allowed.iter().any(|a| a == ext.to_string_lossy().as_ref())
    } else {
        false
    }
}

async fn fetch_resource(
    config: &ConsumerConfig,
    relative_path: &str,
) -> Result<String, Box<dyn std::error::Error + Send + Sync>> {
    let sanitized = sanitize_path_component(relative_path);
    let target = config.base_dir.join(&sanitized);
    let canonical_base = fs::canonicalize(&config.base_dir).await?;
    let canonical_target = fs::canonicalize(&target).await?;

    if !is_within_base(&canonical_base, &canonical_target) {
        return Err("Access denied: path traversal detected".into());
    }

    // Enforce allowed-extension filtering on fetch as well, consistent with listing,
    // to prevent disclosure of sensitive file types.
    let name = canonical_target
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_default();
    if !has_allowed_extension(&name, &config.allowed_extensions) {
        return Err("Access denied: file type not allowed".into());
    }

    let content = fs::read_to_string(&canonical_target).await?;
    Ok(content)
}

async fn emit_response(
    _msg_id: &str,
    _entries: Vec<String>,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    // In production, this would publish to a response queue
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[tokio::test]
    async fn test_basic_listing() {
        let dir = tempdir().unwrap();
        std::fs::write(dir.path().join("test.json"), "{}").unwrap();
        let config = ConsumerConfig::new(dir.path().to_path_buf());
        let result = resolve_and_list(&config, "").await.unwrap();
        assert!(result.contains(&"test.json".to_string()));
    }
}
